// 结果端口夹具仅提供本测试实际结算后登记的来源；缺失源仍应拒绝。
struct Results final:GrowthLifeRead {
    std::optional<LifeActivityView> result;
    std::optional<LifeActivityView> life_result(const StableId& id)const override{return result&&result->action_id==id?result:std::nullopt;}
    std::vector<StableId> life_fact_ids(Integer,Integer)const override{return result?std::vector<StableId>{result->fact_id}:std::vector<StableId>{};}
};
// 组织端口在此不提供新责任；会话投影仍读取真实InteractionState。
struct Organizations final:OrganizationRead {
    bool organization_exists(const StableId&)const override{return true;}
    bool organization_active(const StableId&)const override{return true;}
    bool institutional_obligation_allowed(const StableId&,const StableId&,const StableId&,const StableId&,Integer,Integer)const override{return false;}
    bool actor_accepts_duty(const StableId&,const StableId&)const override{return true;}
    std::optional<Integer> authority_epoch(const StableId&)const override{return {};}
    Outcome<AuthorityProof> authorize(const ActingAuthority&,const StableId&,const ScopeRef&,Integer)const override{return {false,{},common_failure("AuthorityUnavailable").error};}
    std::optional<OrganizationMemberView> member_view(const StableId&,const StableId&)const override{return {};}
};
